package cl.nexbyte.siger.institucional.nucleo;
import cl.nexbyte.siger.institucional.robustez.*;import cl.nexbyte.siger.institucional.identidad.AutoridadesInstitucionales;import java.nio.file.Path;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;import static cl.nexbyte.siger.institucional.nucleo.ContratosNucleo.*;

class AccesoReservadoTest {
 @TempDir Path temp;DatosNucleoTest d;AccesoReservadoFixture f;RevisionExcepcionalFixture x;AreasInstitucionalesTest.Reloj clock;
 @BeforeEach void setup()throws Exception{clock=new AreasInstitucionalesTest.Reloj();String mysql=System.getProperty("siger.test.autoridad.mysql");d=new DatosNucleoTest(temp,mysql==null?null:mysql+"_reserva?sslMode=DISABLED&allowPublicKeyRetrieval=true&connectTimeout=3000&socketTimeout=10000");if(mysql!=null)limpiar();f=new AccesoReservadoFixture(d,clock);x=f.x;}
 void limpiar(){d.limpiar();for(var t:List.of("staff_profile_history","identity_event","staff_assignment","staff_account","org_coverage"))d.db.sql.update("DELETE FROM "+t);}
 @AfterEach void close(){if(d!=null){if(System.getProperty("siger.test.autoridad.mysql")!=null)limpiar();d.close();}}
 UUID key(){return UUID.randomUUID();}void denied(int code,Runnable work){assertEquals(code,assertThrows(FalloTecnico.class,work::run).status);}
 ContenidoInstitucional.Permisos permiso(String actor,UUID doc){return x.f.core.contenidos().permisos(x.f.a(actor),x.cas,doc);}
 @Test void dobleRespaldoAbreSoloDocumentoCuentaYConsultaExpresaSinGestion(){UUID doc=x.documento("FIR"),other=x.documento("FIR");denied(404,()->permiso(x.reviewer,doc));UUID id=f.proponer(doc,true,false);denied(404,()->permiso(x.reviewer,doc));f.aprobar(id);var p=permiso(x.reviewer,doc);assertTrue(p.contenido());assertFalse(p.descarga());assertFalse(p.administrar());assertFalse(p.restringir());denied(404,()->permiso(x.alias,doc));denied(404,()->permiso(x.f.ti,doc));denied(404,()->permiso(x.reviewer,other));denied(404,()->x.f.core.contenidos().permisos(x.f.a(x.reviewer),x.other,doc));assertFalse(x.f.a(x.reviewer).jefeEn("UPR","DEMO_SEDE_A","AREA_A"));assertEquals(1,d.db.sql.queryForObject("SELECT COUNT(*) FROM institution_sensitive_access",Long.class));}
 @Test void metadatosNoConcedenContenidoDescargaOHistorial(){UUID doc=x.documento("FIR"),id=f.proponer(doc,false,false);f.aprobar(id);var p=permiso(x.reviewer,doc);assertFalse(p.contenido());assertFalse(p.descarga());x.f.core.contenidos().autorizarDocumento(x.f.a(x.reviewer),x.cas,doc,"METADATOS");for(String action:List.of("CONTENIDO","DESCARGA","HISTORIAL"))denied(404,()->x.f.core.contenidos().autorizarDocumento(x.f.a(x.reviewer),x.cas,doc,action));}
 @Test void contextoNoRevelaLaExistenciaDeDocumentosDeOtroCaso(){UUID doc=x.documento("FIR");denied(404,()->f.flow.contexto(x.f.a(x.owner),x.other,doc));denied(404,()->f.flow.contexto(x.f.a(x.owner),x.other,key()));denied(404,()->f.flow.proponer(x.f.a(x.owner),key(),x.other,doc,new AccesoReservado.Proponer(1,x.reviewer,clock.instant(),clock.instant().plusSeconds(120),true,false,"No autorizar por compartir REQ")));assertEquals(0,d.db.sql.queryForObject("SELECT COUNT(*) FROM institution_sensitive_access",Long.class));}
 @Test void permiteCompletarSubContConFirSinConcederOtrosExpedientes(){UUID doc=x.documento("FIR");UUID grant=f.proponer(doc,true,true);f.aprobar(grant);UUID review=x.solicitar();x.aprobar(review);x.flow.confirmar(x.f.a(x.reviewer),key(),review,x.confirmacion(review));assertEquals("CERRADO",x.f.core.caso(x.f.a(x.reviewer),x.cas).estado());assertEquals("EXCEPCIONAL",x.f.core.caso(x.f.a(x.reviewer),x.cas).modalidadCierre());denied(404,()->x.f.core.caso(x.f.a(x.reviewer),x.other));assertEquals("ACTIVO",d.db.sql.queryForObject("SELECT state FROM core_requirement WHERE id=?",String.class,x.req.toString()));assertEquals("a".repeat(64),d.db.sql.queryForObject("SELECT sha256 FROM institution_document WHERE id=?",String.class,doc.toString()));}
 @Test void noAutoaprobacionAunqueSeAcumulenFacultadesNiPorAlias()throws Exception{UUID doc=x.documento("FIR");f.caps=List.of(f.cap(f.gestion,"GESTION_A","ACTIVA"),f.cap(x.owner,"GESTION_OWNER","ACTIVA"),f.cap(x.reviewer,"GESTION_REVISOR","ACTIVA"));f.publicar();UUID grant=f.proponer(doc,true,false);for(String actor:List.of(x.owner,x.reviewer,x.alias))denied(403,()->f.flow.decidir(x.f.a(actor),key(),grant,new AccesoReservado.Decidir(0,"No autoaprobar por cuentas alternativas"),"APROBAR"));f.aprobar(grant);denied(404,()->permiso(x.alias,doc));}
 @Test void revocacionVigenciaYSuspensionCierranConLaMismaCuenta()throws Exception{UUID doc=x.documento("FIR"),grant=f.proponer(doc,true,true);f.aprobar(grant);assertTrue(permiso(x.reviewer,doc).descarga());f.flow.decidir(x.f.a(f.gestion),key(),grant,new AccesoReservado.Decidir(1,"Retiro de respaldo específico"),"REVOCAR");denied(404,()->permiso(x.reviewer,doc));UUID next=f.proponer(doc,true,false);f.aprobar(next);f.caps=List.of(f.cap(f.gestion,"GESTION_A","SUSPENDIDA"));f.publicar();denied(404,()->permiso(x.reviewer,doc));f.caps=List.of(f.cap(f.gestion,"GESTION_A","ACTIVA"));f.publicar();assertTrue(permiso(x.reviewer,doc).contenido());clock.now=clock.now.plusSeconds(121);denied(404,()->permiso(x.reviewer,doc));f.flow.bandeja(x.f.a(x.owner));assertEquals("EXPIRADA",d.db.sql.queryForObject("SELECT state FROM institution_sensitive_access WHERE id=?",String.class,next.toString()));}
 @Test void nuevaProteccionNoReactivaUnaDecisionAnteriorNiAceptaInstruccionAlterada(){UUID doc=x.documento("FIR"),id=f.proponer(doc,true,true);f.aprobar(id);x.f.core.contenidos().proteger(x.f.a(x.owner),key(),x.cas,doc,new ContenidoInstitucional.Proteccion(1,"ORDINARIO","Rectificación fundada de protección"));x.f.core.contenidos().proteger(x.f.a(x.owner),key(),x.cas,doc,new ContenidoInstitucional.Proteccion(2,"FIR","Nueva reserva requiere respaldo actual"));denied(404,()->permiso(x.reviewer,doc));d.db.sql.update("UPDATE institution_sensitive_access SET policy_revision=3 WHERE id=?",id.toString());denied(404,()->permiso(x.reviewer,doc));denied(409,()->f.flow.decidir(x.f.a(f.gestion),key(),id,new AccesoReservado.Decidir(1,"No aceptar fila alterada"),"REVOCAR"));assertEquals("ACTIVA",d.db.sql.queryForObject("SELECT state FROM institution_sensitive_access WHERE id=?",String.class,id.toString()));}
 @Test void retiroDeEquipoCierraListadosAvisosYDocumentosSinEliminarHistorial(){UUID doc=x.documento("FIR"),id=f.proponer(doc,true,false);f.aprobar(id);assertTrue(f.flow.bandeja(x.f.a(x.reviewer)).stream().anyMatch(r->id.toString().equals(r.get("id"))));x.f.core.equipo().retirar(x.f.a(x.owner),key(),x.cas,new EquipoCaso.Retirar(x.rev(),x.reviewer,null,"Retiro de participación autorizado"));denied(404,()->permiso(x.reviewer,doc));assertTrue(f.flow.bandeja(x.f.a(x.reviewer)).isEmpty());assertFalse(f.flow.autorizarAviso(x.f.a(x.reviewer),id));assertEquals(1,d.db.sql.queryForObject("SELECT COUNT(*) FROM institution_sensitive_access WHERE id=?",Long.class,id.toString()));}
 @Test void rechazoRetiroYReintentoNoRehabilitanNiFabricanRoles(){UUID doc=x.documento("FIR");UUID id=f.proponer(doc,true,false);f.flow.decidir(x.f.a(f.gestion),key(),id,new AccesoReservado.Decidir(0,"Rechazo fundado"),"RECHAZAR");denied(404,()->permiso(x.reviewer,doc));UUID next=f.proponer(doc,true,false);var k=key();var request=new AccesoReservado.Decidir(0,"Aprobación específica");var result=f.flow.decidir(x.f.a(f.gestion),k,next,request,"APROBAR");f.flow.decidir(x.f.a(x.owner),key(),next,new AccesoReservado.Decidir(1,"Revocación por jefatura"),"REVOCAR");assertEquals(result,f.flow.decidir(x.f.a(f.gestion),k,next,request,"APROBAR"));denied(404,()->permiso(x.reviewer,doc));UUID last=f.proponer(doc,true,false);f.flow.decidir(x.f.a(x.owner),key(),last,new AccesoReservado.Decidir(0,"Retirada expresa"),"RETIRAR");assertEquals("RETIRADA",d.db.sql.queryForObject("SELECT state FROM institution_sensitive_access WHERE id=?",String.class,last.toString()));}
 @Test void idempotenciaConcurrenciaYVersionImpidenDobleConcesion()throws Exception{UUID doc=x.documento("FIR"),k=key();var request=new AccesoReservado.Proponer(1,x.reviewer,clock.instant(),clock.instant().plusSeconds(120),true,false,"Respaldo de jefatura único");var start=new CountDownLatch(1);UUID grant;try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->{start.await();return f.flow.proponer(x.f.a(x.owner),k,x.cas,doc,request);});var b=pool.submit(()->{start.await();return f.flow.proponer(x.f.a(x.owner),k,x.cas,doc,request);});start.countDown();var result=a.get(8,TimeUnit.SECONDS);assertEquals(result,b.get(8,TimeUnit.SECONDS));grant=result.id();}f.aprobar(grant);denied(409,()->f.flow.decidir(x.f.a(f.gestion),key(),grant,new AccesoReservado.Decidir(0,"Versión anterior no decide dos veces"),"APROBAR"));assertEquals(1,d.db.sql.queryForObject("SELECT COUNT(*) FROM institution_sensitive_access",Long.class));assertEquals(1,d.db.sql.queryForObject("SELECT COUNT(*) FROM authority_event WHERE resource_id=? AND action_code='RESERVA_APROBAR'",Long.class,grant.toString()));}
 @Test void firmaAnteriorNoSeReinterpretaComoFacultadDeReserva()throws Exception{UUID doc=x.documento("FIR");var r=x.common;long rev=d.db.sql.queryForObject("SELECT revision FROM authority_registry WHERE id=1",Long.class)+1;var payload=d.mapper.valueToTree(new AutoridadesInstitucionales.Registro16("1.5",rev,clock.instant(),x.f.end,r.vinculos(),r.mandatos(),r.areas(),r.ambitos(),r.cambiosArea(),r.materias(),r.sedesRegionales(),r.ambitosMateria(),r.principales(),x.s.funciones,x.caps,f.caps));denied(400,()->{try{x.f.importar(payload);}catch(FalloTecnico e){throw e;}catch(Exception e){throw new IllegalStateException(e);}});x.publicar();assertTrue(x.f.f.autoridades.contextoReserva(x.owner).facultades().isEmpty());denied(409,()->f.proponer(doc,true,false));}
 @Test void autoridadDeOtraAreaNoRespaldaLaReservaAunqueSeaDeLaMismaUnidad()throws Exception{UUID doc=x.documento("FIR"),id=f.proponer(doc,true,false);f.aprobar(id);var old=f.caps.getFirst();f.caps=List.of(new AutoridadesInstitucionales.FacultadReserva(old.id(),old.persona(),old.unidad(),old.sede(),"AREA_B",old.materia(),old.desde(),old.hasta(),old.referencia(),old.sha256(),old.estado()));f.publicar();denied(404,()->permiso(x.reviewer,doc));assertFalse((Boolean)f.flow.contexto(x.f.a(x.owner),x.cas,doc).get("gestionAcreditada"));}
 @Test void dosAutoridadesNoPuedenConcederseAccesosReciprocos()throws Exception{
  x.f.core.revisarCaso(x.f.a(x.owner),key(),x.cas,new Decision(x.rev(),"Retoma gestión para configurar equipo"),"DEVOLUCION");x.f.otorgar(x.f.headA,"PROFESIONAL","AREA_A");x.f.core.equipo().incorporar(x.f.a(x.owner),key(),x.cas,new EquipoCaso.Incorporar(x.rev(),x.f.headA,"Participación expresa para revisión"));
  f.gestion=x.f.headA;f.caps=List.of(f.cap(f.gestion,"GESTION_TITULAR","ACTIVA"),f.cap(x.reviewer,"GESTION_REVISOR","ACTIVA"));f.publicar();UUID doc=x.documento("FIR"),first=f.proponer(doc,true,false);f.aprobar(first);
  UUID second=f.flow.proponer(x.f.a(x.owner),key(),x.cas,doc,new AccesoReservado.Proponer(1,x.f.headA,clock.instant(),clock.instant().plusSeconds(120),true,false,"Propuesta que aún requiere Gestión independiente")).id();denied(403,()->f.flow.decidir(x.f.a(x.reviewer),key(),second,new AccesoReservado.Decidir(0,"No se acepta aprobación recíproca"),"APROBAR"));assertEquals("PENDIENTE",d.db.sql.queryForObject("SELECT state FROM institution_sensitive_access WHERE id=?",String.class,second.toString()));
 }
 @Test void avisosDobleCanalSonMinimosDeduplicadosYNoOtorganLecturaATi(){UUID doc=x.documento("FIR"),id=f.proponer(doc,true,false);f.aprobar(id);var resources=new cl.nexbyte.siger.institucional.notificaciones.RecursosNotificacion(d.db,x.f.cat,x.f.core);var notices=new cl.nexbyte.siger.institucional.notificaciones.NotificacionesInstitucionales(d.db,x.f.cat,resources,clock);for(int i=0;i<5;i++)notices.proyectar();long count=d.db.sql.queryForObject("SELECT COUNT(*) FROM institution_notification WHERE resource_type='RESERVA_DOC' AND resource_id=?",Long.class,id.toString());assertTrue(count>=6);assertEquals(0,notices.proyectar());assertEquals(count,d.db.sql.queryForObject("SELECT COUNT(*) FROM institution_notification WHERE resource_type='RESERVA_DOC' AND resource_id=?",Long.class,id.toString()));assertEquals(0,d.db.sql.queryForObject("SELECT COUNT(*) FROM institution_notification WHERE resource_type='RESERVA_DOC' AND recipient_id=?",Long.class,x.f.ti));assertEquals(count,d.db.sql.queryForObject("SELECT COUNT(*) FROM notification_outbox o JOIN institution_notification n ON n.id=o.notification_id WHERE n.resource_type='RESERVA_DOC' AND n.resource_id=? AND o.state='PENDIENTE'",Long.class,id.toString()));assertEquals(0,d.db.sql.queryForObject("SELECT COUNT(*) FROM mail_attempt",Long.class));}
}
